import numpy as np

demo_regions = [
    np.array([[8, 8, 8, 0], [8, 0, 8, 0], [0, 0, 0, 8], [0, 8, 0, 0]]),  # R0
    np.array([[5, 5, 5, 0], [5, 5, 5, 5], [5, 5, 0, 0], [0, 5, 5, 5]]),  # R1
    np.array([[9, 9, 9, 0], [9, 9, 0, 9], [0, 0, 0, 0], [9, 0, 0, 0]]),  # R2
    np.array([[4, 4, 4, 4], [0, 0, 0, 0], [0, 4, 4, 0], [4, 4, 4, 4]])   # R3
]

demo_output = np.array([
    [9, 9, 9, 4],
    [9, 9, 8, 9],
    [5, 4, 4, 8],
    [9, 4, 4, 4]
])

# Final hypothesis:
# 1. If R2 present: output = R2's value
# 2. Else if R3 present: output = R3's value
# 3. Else if R1 present: output = R1's value
# 4. Else if R0 present: output = R0's value

print("Testing final priority: R2 > R3 > R1 > R0:")
correct = 0
for r in range(4):
    for c in range(4):
        # Find values from each region at this position
        reg_vals = {}
        for i in range(4):
            if demo_regions[i][r, c] != 0:
                reg_vals[i] = demo_regions[i][r, c]

        if 2 in reg_vals:
            pred = reg_vals[2]
        elif 3 in reg_vals:
            pred = reg_vals[3]
        elif 1 in reg_vals:
            pred = reg_vals[1]
        elif 0 in reg_vals:
            pred = reg_vals[0]
        else:
            pred = 0

        actual = demo_output[r, c]
        match = "✓" if pred == actual else "✗"
        if pred == actual:
            correct += 1

        if pred != actual:
            print(f"  ({r},{c}): reg_vals={reg_vals}, predict={pred}, actual={actual} {match}")
        elif correct <= 5:
            pass  # Print some info for debugging

print(f"\nCorrect: {correct}/{16}")

